import{_ as e,c as t,o as p,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易玩辞","description":"周易玩辞 - 周易玩辞","frontmatter":{"title":"周易玩辞","description":"周易玩辞 - 周易玩辞"},"headers":[],"relativePath":"zh/classics/wanci/001.md","filePath":"zh/classics/wanci/001.md"}'),c={name:"zh/classics/wanci/001.md"};function r(i,a,n,_,o,l){return p(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="周易玩辞" tabindex="-1">周易玩辞 <a class="header-anchor" href="#周易玩辞" aria-label="Permalink to “周易玩辞”">​</a></h1><p>钦定四库全书经部一</p><p>易类提要</p><p>臣 等谨案：周易玩辞十六卷，宋项安世撰。安世字平甫，松阳人。馆阁续录载其淳熙二年同进士出身，绍熙五年除校书郎，庆元元年添差通判池州。陈振孙书录解题称为太府卿，则所终之官也。事迹具宋史本传。振孙乂称安世当庆元时，谪居江陵，杜门不出。诸经皆有论说，而易为全书。然据其自述，盖成于</p><p>嘉泰二年壬戌之秋。自序谓：「易之道四，其实则二，象与辞是也。变则象之进退也，占则辞之吉凶也。不识其象，何以知其变？不通其辞，何以决其占？」又自述曰：「安世之所学，盖伊川程子之书也。今以其所得于易传者述为此书，而其文无与易传合者，合则无用述此书矣。」盖伊川易传惟阐义理，安世则兼象数而求之。其意欲于程传之外补所不及，所谓各明一义者也。马端临、虞集作序，皆盛相推挹。而近时王懋竑白田杂著中有是书跋，独排斥甚力，至谓端临等未观其书。其殆安世自述中所谓以易传之文观我者欤？安世又有项氏家说，其第一卷亦解易，董真卿尝称之。世无传本，今始以永乐大典所载裒合成编，别著于录。合观两书，安世之经学深矣，何可轻诋也。乾隆四十二年二月恭校上。</p><p>总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。周易玩辞序：</p><p>周易玩辞者，江陵项公安世平甫之所著也。其言以为大传曰：「君子居则观其象而玩其辞，动则观其变而玩其占。」其道虽四，而实则二。变乃象之进退，占乃辞之吉凶。圣人因象以措辞，后学因辞而测象，是故学易者，舍辞何以哉？项公以其玩于辞而得之者笔于书，使后之学者，因其言皆有以玩于前圣之辞而得焉，此项氏著书之意也。嗟夫！天不言，生圣人而代之言，故曰圣人之精，画卦以示。圣人之蕴，因卦以发。微卦。圣人之蕴，殆不可悉得而闻。然卦象未有语言，自非明知，何以知之？中古圣人，以其忧患之心，因卦立言，畅于周公，究于孔子，首尾具完，皆所亲定。所谓精与蕴者，后世因得以推见焉。今夫生乎千载之下，而仰观于千载之上，以凡人之资，而欲窥见天与圣人之道，苟得于圣人之一言，即为天之命已矣。况乎三圣人之言，广大悉备，虽历世久远，遭时丧乱，亘千万古，而与所谓卦画者，略不可有所磨灭，岂非天乎？后之立言，岂有加于此者？志于学者，诚不可下此而他求己。愚是以深叹项公之为知言。汉晋以来，治易之师，其言犹有可见，而于四圣人之意，未知其何如也。及乎邵子、周子之生，易道盖中兴焉。邵子以先天心学著为成书，不必丽乎经传，而极天地之妙，通万物之情，三圣人以降，未之或先，而学者鲜或知之。周子之图，亦不必求同于易象，而理则不二。所谓通书者，皆所以通乎易者也。因卦以立辞者，如乾、损、益、家人、睽、复、无妄、蒙、艮之说仅见。如大畜等卦，当时已不得闻。独赖河南程子亲得其宗，以其成德之能事，附于三圣人之书而言之，非直传注而已也。自其学而推之，以极其至，则天人之际，岂有间哉？盖尝闻之，能尽其性者，则能尽人之性；能尽人之性，则能尽物之性。故曰：「知其性，则知天矣。」苟知天矣，则天地之故，鬼神之迹，事物之杂，岂待于考索推测而后通之？故程子有言不尽意者，诚有望于后世学者，自有得于圣人也。朱子发明象占本义，多约程子之言而精之云尔。故学易之士，于是得其端绪而不差焉。项公实与朱子同时，当时则又有江西陆先生者，各以其学为教。又有聪明文学过人之士，兴于永嘉，项公尝从而问辨咨决焉。其遗文犹有可征者。朱、项往来之书，至六七而不止，其要旨直以程子「涵养须用敬，进学则在致知」之说以告之。于是项公之学，上不过于高虚，下不陷于功利，而所趋所达，端有定向。然后研精覃思，作为此书。外有以采择诸家之博闻，内有以及乎象数之通变，奇而不凿，深而不迂，详而无余，约而无阙，庶几精微之道焉。其书既成，而朱子殁矣。自序其学皆出于程子，而其言则不必皆同也，是可以见其讲明之指归矣。近时学易君子，多有取于其说，岂徒然哉？然而为是学者，自非深求于程朱之说，而有所愤悱于缺塞，则亦不足以知项氏之功也。集之壮岁，至好此书，每取其说，以与朋友讲习。今淮西廉访佥事干君克庄，好古博雅，学道爱人，尝以礼学贡于有司而不及奏，有旨俾居成均，勤苦数载，有人所不能堪者。及文宗皇帝临御，开延阁以待天下之士，乃特召见，得与论思之次，一时谓之得人。持节淮𤲬，至于江上，取是书于箧，俾齐安郡学刻而广之，盖叹乎学者之不多见是书也。不鄙谓集退老林下，庶乎困学之不敢忘，俾叙其说焉。呜呼！内圣外王之学不明于后世，而为治者以其知力之所及而行之，不无其效。至若上下与天地同流者，则何有哉？昔邵子有言曰：「学于里人而尽里人之情，学于乡人而尽乡人之情，学于国人而尽国人之情，学于古人而尽古人之情，学于天地而尽天地之情。」如此，则可以玩辞观象而得之，世有斯人也哉！后学虞集谨书。周易玩辞序</p><p>予幼嗜易，祖程传，宗本义。诸儒训解中，取平庵项氏玩辞熟读精思，道德性命之原，开物成务之故，一出于奇耦往来不穷之变，曰象与占随时取义玩辞。可知先生此书，不特有裨于程子七分之传，当时往复问学朱子之门，其于本义多所发明。惜书成于本义二十年之后，朱子未及见也。集贤初庵傅公以易学经世，被遇殊休，俾其徒黄棠创建精庐，嘉惠后学，经府传窟中独缺此书。予过梧翁先生马公考学，得所藏本，乃咸淳乙丑礼部贡院所点校，敬锓诸梓，与朋友共，使家藏而人诵之，予之志也。大德丁未孟秋冷掾徐之祥拜手谨书。周易玩辞序</p><p>易有圣人之道四，变与象居其二焉。自义理之学大明，而变象之说几晦。先儒欲救其弊，则曰：「圣人当时自可别作一书，明言义理，以诏后世，何用假托卦爻，为此艰深隐晦之辞乎？」愚尝以为变之说不一，有随时之变，如彖、象、小象、文言、繋辞，各自一义是也；有逐爻之变，如六九七八、阴阳老少是也；有逐卦之变，如刚柔往来、互体飞伏是也。象之说亦不一，有卦画之象，阴阳奇耦、三连六断是也；有大象之象，天地风雷山泽水火是也；有说卦之象，「乾为马，坤为牛」、「乾为首、坤为腹」之类是也。至简要者，随时之变也；至支离者，逐卦之变也；至精微者，卦画之象也；至琐碎者，说卦之象也。必研究其简要精微者，而不拘泥其支离琐碎者，则曰象曰变，固无非精义至理之所寄也，岂有二哉？平庵项公玩辞之书，义理渊源伊洛，而于象变之际，䌷绎尤精，明畅正大，无牵合附会之癖。公尝谓必徧通五经，而后归老于易。且自言窥其门墙，而未极其穾奥，今将尽心焉。则是书必暮年所著，家有善本，先公尝熟复而手校之。方塘徐君掌教初庵，以是书锓梓学舍，俾赘语其编尾，辄诵所闻。大德丁未菊月后学马端临谨书。周易玩辞序</p><p>序曰：大传曰：「君子居则观其象而玩其辞，动则观其变而玩其占。」读易之法，尽于此矣。易之道四，其实则二，象与辞是也。变则象之进退也，占则辞之吉凶也。不识其象，何以知其变？不通其辞，何以决其占？然而圣人因象以措辞，后学因辞而测象，则今之读易，所当反复䌷绎、精思而深味者，莫辞若也。于是作周易玩辞。宋庆元四年岁次戊午秋九月己未，江陵项安世述。周易上篇六卷，周易下篇六卷，系辞两卷，说卦一卷，序卦、杂卦一卷。</p><p>嘉泰二年壬戌之秋，重修周易玩辞十六卷。章句粗定，因自叹曰：「安世之所学，盖伊川程子之书也。」程子平生所著，独易传为全书，安世受而读之三十年矣。今以其所得于易传者述为此书，而其文无与易传合者，合则无用述此书矣。世之友朋以易传之理观吾书，本末条贯，无一不本于易传者；以易传之文观吾书，则未免有使西河之民疑汝于夫子之怒。知我者，此书也；罪我者，此书也。九月丙午，安世谨书。</p>',11)])])}const m=e(c,[["render",r]]);export{h as __pageData,m as default};
